local _, WFJ = ...
WFJ.Data.add("book", {
  ["ba0b5949266e993d"] = { "I lunghi secoli che seguirono la Grande Separazione del mondo furono difficili per la razza troll. Carestie e terrore erano all'ordine del giorno nei regni frantumati. I troll Gurubashi, spinti alla disperazione, cercarono l'aiuto di antiche forze mistiche. Benché entrambi i regni troll condividessero la fede in un grande pantheon di divinità primitive, i Gurubashi caddero sotto l'influsso della più oscura di esse.", "." },
  ["ba20442bef27a4cf"] = { "Questo cimelio della Seconda Guerra è un vivido monito di quanto l'⟦Horde=Orda⟧ sia andata pericolosamente vicina a conquistare la montagna di ⟦Ironforge=Forgiardente⟧.", "." },
  ["ba70cf77e24b047b"] = { "Anche se non è chiaro che cosa li abbia risvegliati, i terrigeni sigillati dentro Uldaman finirono per destarsi dal sonno che si erano imposti. Questi terrigeni scoprirono di essere cambiati profondamente durante il loro letargo. Le loro scorze rocciose si erano ammorbidite, diventando pelle liscia, e il loro potere sulla pietra e sulla terra si era affievolito. Erano diventati creature mortali.", "." },
  ["ba964235067bcdd7"] = { "Curgle,\n\nattendo con impazienza la tua ultima invenzione. Non vedo l'ora di cominciare a usarla per documentare i miei studi.\n\nTi prego di affidarla al mio messaggero.\n\nCon i più cordiali saluti,\n\nDaryn Lightwind", "." },
  ["baa579dd88e695ec"] = { "Progettando di scatenare le sue forze e i possenti draghi rossi contro l'⟦Alliance=Alleanza⟧, Nekros sperava di riunire l'⟦Horde=Orda⟧ e di proseguire la conquista di Azeroth. La sua visione non si realizzò: un piccolo gruppo di combattenti della resistenza, guidato dal mago umano Rhonin, riuscì a distruggere la Demon Soul e a liberare la Regina dei Draghi dal controllo di Nekros.", "." },
  ["baf607ec0ca4dee7"] = { "Darò a Ironpatch l'ordine di aprire il fuoco con i cannoni. Il fuoco d'artiglieria impedirà a qualsiasi nave degli Acquanera di uscire dal porto o di entrarvi.\n\nQuando il ⟦The Crimson Veil=Velo Cremisi⟧ avrà scaricato i suoi cannoni, lo porterò accanto alla ⟦The Riptide=Granmarea⟧ come supporto e fornirò rinforzi secondo necessità.\n\nUna volta che Salthoof e i suoi ragazzi avranno dato fuoco alla città e saranno tutti a bordo, spiegheremo le vele e daremo alla Baia un'ultima cannonata dalla Costa Selvaggia, tanto per gradire.\n\n--Ammiraglio Firallon", "." },
})
